def central_angles(example=False):
 if example:
  center=(235,190);scale=37
  def pt(x,y):return(235+scale*x,190-scale*y)
  a,b,c=pt(-3,0),pt(2,-sqrt(5)),pt(2,sqrt(5));radius=111
  labels=[(a[0]-19,a[1]-10,'A'),(b[0]+4,b[1]+14,'B(2,−√5)'),(c[0]+4,c[1]-10,'C(2,√5)'),(222,211,'O'),(392,196,'x'),(231,48,'y')]
  axes=[path([(80,190),(386,190)]),path([(235,320),(235,58)])]
 else:
  center=(240,180);radius=100;a=(240,80);b=(160,240);c=(320,240)
  labels=[(241,69,'A(0,a)'),(139,258,'B'),(323,258,'C'),(220,178,'O'),(367,185,'x'),(233,40,'y')];axes=[path([(115,180),(361,180)]),path([(240,303),(240,50)])]
 paths=[path(ellipse(*center,radius,radius)),*axes,path([b,a,c]),path([b,center,c])]
 return geometry('Figure 8.18' if example else 'Figure 8.17','Exact source circle and vertices for Example 17' if example else 'Figure 8.17 — inscribed angle at A and central angle subtending minor arc BC',paths,labels,size=(470,340))
def semicircle():
 c=(250,180);a=(350,180);b=(150,180);p=(190,100)
 return geometry('Figure 8.19','Figure 8.19 — diameter AB and non-endpoint circumference point P make a right angle',[path(ellipse(*c,100,100)),path([(120,180),(390,180)]),path([(250,300),(250,50)]),path([a,p,b]),path([(198.944272,104.472136),(194.472136,113.416408),(185.527864,108.944272)])],[(254,42,'y'),(394,186,'x'),(351,203,'A'),(130,203,'B'),(237,201,'O'),(150,87,'P(x₁,y₁)'),(197,131,'90°')],size=(450,330))
PAGES=[page('122_page_1.jpg',235,[paragraph('From the Figure 8.17, if ∠BAC = θ and ∠BOC = 2θ, then, result (ii) can be verified as follows: If the slopes of BA and AC are'),central_angles(),eq(r'm_1=\frac{a+y_1}{x_1},\quad m_2=\frac{-y_1-a}{x_1}=-\frac{a+y_1}{x_1}'),paragraph('then, the angle ∠BAC = θ from BA to AC is:'),eq(r'\tan\theta=\frac{m_1-m_2}{1+m_1m_2}=\frac{(a+y_1)/x_1+(a+y_1)/x_1}{1-[(a+y_1)/x_1][(a+y_1)/x_1]}'),eq(r'=\frac{2(a+y_1)}{x_1}\cdot\frac{x_1^2}{x_1^2-(a+y_1)^2}=\frac{2x_1(a+y_1)}{x_1^2-a^2-y_1^2-2ay_1}'),eq(r'=\frac{2x_1(a+y_1)}{-2y_1^2-2ay_1}=\frac{2x_1(a+y_1)}{-2y_1(a+y_1)}=-\frac{x_1}{y_1},\quad x_1^2+y_1^2=a^2','iii'),paragraph('If the slopes of BO and CO are m₃ = y₁/x₁, m₄ = −y₁/x₁, then the angle ∠BOC = 2θ from BO to OC is:'),eq(r'\tan2\theta=\frac{m_3-m_4}{1+m_3m_4}=\frac{y_1/x_1+y_1/x_1}{1-(y_1/x_1)(y_1/x_1)}=\frac{2x_1y_1}{x_1^2-y_1^2}','iv'),paragraph('The trigonometric identity'),eq(r'\tan2\theta=\frac{2\tan\theta}{1-\tan^2\theta}=\frac{-2x_1/y_1}{1-x_1^2/y_1^2}=\frac{-2x_1y_1}{y_1^2-x_1^2}=\frac{2x_1y_1}{x_1^2-y_1^2}'),paragraph('is proving result (iv) with result (iii). Thus ∠BOC = 2∠BAC.'),note('The source’s negative tangent corresponds to a directed line-angle convention. Equality of tangent values alone establishes an angle only modulo 180°, and slope quotients omit vertical or perpendicular special cases. For the symmetric source points B(−x₁,−y₁), C(x₁,−y₁), with x₁,y₁ > 0, the positive inscribed angle is atan2(x₁,y₁), and the minor central angle is twice that value, in (0°,180°). Checking vertex rays resolves the sign and branch rather than calling a negative principal angle an interior angle.'),
 heading('Example 17'),paragraph('Show that the angle subtended by the minor arc BC of the circle x²+y² = 9 is two times the angle subtended in the major arc of the circle. The coordinates of the minor arc are B(2,√5), C(2,−√5).'),heading('Solution'),paragraph('The circle x²+y² = 9, whose center is O(0,0). The arc BC is the minor arc of the given circle, whose coordinates are B(2,√5), C(2,−√5) and the minor arc BC subtended the angle from the center of the circle is ∠BOC. If A(−3,0) is a point on the major arc, then join AB and AC that develops the angle of the minor arc which is two times the angle subtended by the major arc:'),eq(r'\angle BOC=2\angle BAC','i'),central_angles(True),paragraph('From the Figure 8.18, if ∠BAC = θ and ∠BOC = 2θ, then, result (v) can be verified as follows: If the slopes of BA and AC are'),eq(r'm_1=\frac{0+\sqrt5}{-3-2}=-\frac1{\sqrt5},\quad m_2=\frac{\sqrt5-0}{2+3}=\frac1{\sqrt5}'),paragraph('then, the angle ∠BAC = θ from BA to AC is:'),eq(r'\tan\theta=\frac{m_1-m_2}{1+m_1m_2}=\frac{1/\sqrt5+1/\sqrt5}{1-1/5}=\frac{2/\sqrt5}{4/5}=\frac{\sqrt5}2','ii')]),
 page('122_page_2.jpg',236,[paragraph('If the slopes of BO and OC are'),eq(r'm_3=\frac{0+\sqrt5}{-2}=-\frac{\sqrt5}2,\quad m_4=\frac{\sqrt5-0}2=\frac{\sqrt5}2'),paragraph('then, the angle ∠BOC = 2θ from OC to BO is'),eq(r'\tan2\theta=\frac{m_4-m_3}{1+m_3m_4}=\frac{\sqrt5/2+\sqrt5/2}{1-5/4}=-4\sqrt5','iii'),paragraph('The trigonometric identity'),eq(r'\tan2\theta=\frac{2\tan\theta}{1-\tan^2\theta}=\frac{2(\sqrt5/2)}{1-5/4}=-4\sqrt5'),paragraph('is proving result (iii) with result (ii). Thus ∠BOC = 2∠BAC.'),note('The question labels B with positive y and C with negative y, while Figure 8.18 and the subsequent slope calculations use B with negative y and C with positive y. Swapping those endpoint names preserves both unsigned angles. In the displayed θ calculation, m₁−m₂ should be negative for the stated slopes, but the source uses a positive numerator. The checked geometric angles are ∠BAC ≈ 48.189685° and the obtuse ∠BOC ≈ 96.379370°. Its negative tangent is consistent with that obtuse branch, not a negative principal angle.'),
 heading('8.4.6 An angle in a semi-circle is a right angle'),paragraph('Let the circle equation be x²+y² = a² (i). If P(x₁,y₁) is any point on the semicircle and BA is fixed as the diameter of the circle (i) on the x-axis, whose coordinates are A(a,0) and B(−a,0), then the point P(x₁,y₁) lies on the circle (i) that changes the circle equation to x₁²+y₁² = a². Join PA and PB that develops a right angle ∠APB. The angle ∠APB is a right angle, if AP and PB are perpendicular to each other, for which the slopes of AP and PB are respectively:'),semicircle(),eq(r'm_1=\frac{y_1-0}{x_1-a}=\frac{y_1}{x_1-a},\quad m_2=\frac{y_1-0}{x_1+a}=\frac{y_1}{x_1+a}'),paragraph('The product of the slopes of AP and PB is'),eq(r'm_1m_2=\frac{y_1}{x_1-a}\cdot\frac{y_1}{x_1+a}=\frac{y_1^2}{x_1^2-a^2}=\frac{y_1^2}{-y_1^2}=-1,\quad x_1^2+y_1^2=a^2'),paragraph('Thus, PA and PB are perpendicular and the angle ∠APB = 90° is of course a right-angle. If ∠APB = 90°, then P is a point lies on the semicircle, for which the Pythagorean rule:'),eq(r'|PA|^2+|PB|^2=|AB|^2','iii'),paragraph('with substitution of'),eq(r'PA=(a-x_1,0-y_1)\ \Rightarrow\ |PA|^2=[\sqrt{(a-x_1)^2+y_1^2}]^2=(a-x_1)^2+y_1^2'),eq(r'PB=(-a-x_1,0-y_1)\ \Rightarrow\ |PB|^2=[\sqrt{(a+x_1)^2+y_1^2}]^2=(a+x_1)^2+y_1^2'),eq(r'AB=(-a-a,0-0)\ \Rightarrow\ |AB|^2=[\sqrt{(-2a)^2+0^2}]^2=4a^2'),paragraph('gives the locus of P(x₁,y₁):'),eq(r'(a-x_1)^2+y_1^2+(a+x_1)^2+y_1^2=4a^2'),eq(r'a^2+x_1^2-2ax_1+y_1^2+a^2+x_1^2+2ax_1+y_1^2=4a^2'),eq(r'2a^2+2x_1^2+2y_1^2=4a^2\ \Rightarrow\ 2x_1^2+2y_1^2=2a^2\ \Rightarrow\ x_1^2+y_1^2=a^2'),paragraph('which is a circle, P may lie on the upper or the lower semicircle.'),note('Take a > 0 and exclude P = A or P = B, where one angle ray has zero length and ∠APB is undefined. A division-free proof uses (A−P)·(B−P) = x₁²+y₁²−a² = 0; both rays are nonzero, so the angle is 90°. Conversely a right angle gives this same circle equation. The algebraic equation includes the two endpoints, but the right-angle locus excludes them.')])]
